```javascript
const results = [{ title: '<img src=x onerror=alert(1)>' }];

function renderResult(result) {
  const item = document.createElement('li');
  const title = document.createElement('span');
  title.textContent = String(result.title ?? 'Untitled');
  item.append(title);
  return item;
}

const list = document.querySelector('[data-results]');
list.replaceChildren(...results.map(renderResult));
```

```javascript
let scheduled = false;

function renderVisibleRows() {
  console.log('render the current visible range');
}

function requestListRender() {
  if (scheduled) return;
  scheduled = true;
  requestAnimationFrame(() => {
    scheduled = false;
    renderVisibleRows();
  });
}

requestListRender();
requestListRender(); // coalesced into the same scheduled render
```
